#include <stdio.h>

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    int sums[1000] = {0};

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int value;
            scanf("%d", &value);
            sums[j] += value;
        }
    }

    int min = sums[0];
    for (int j = 1; j < M; j++) {
